<?php $p=$product??[]; ?><div class="commerce-editor-layout"><form method="post" class="card" data-protect-unsaved><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)($p['id']??0) ?>"><?php if($error): ?><div class="flash-error" role="alert"><?= e($error) ?></div><?php endif; ?><div class="card-heading"><div><p class="section-kicker">Catalog item</p><h2><?= !empty($p['id'])?'Edit product':'New product' ?></h2><p class="card-subtitle">Set the customer-facing details, price, and availability.</p></div><span class="badge neutral"><?= e($currency) ?></span></div><div class="grid2"><label>Product name<input name="name" maxlength="190" required value="<?= e_attr($p['name']??'') ?>"></label><label>SKU<input name="sku" maxlength="100" required value="<?= e_attr($p['sku']??'') ?>" placeholder="GUMBO-32"></label><label>URL slug<input name="slug" maxlength="190" value="<?= e_attr($p['slug']??'') ?>" placeholder="chicken-andouille-gumbo"></label><label>Price (<?= e($currency) ?>)<input name="price" inputmode="decimal" required value="<?= isset($p['price_minor'])?number_format((int)$p['price_minor']/100,2,'.',''):e_attr($p['price']??'') ?>" placeholder="24.00"></label></div><input type="hidden" name="currency" value="<?= e_attr($currency) ?>"><label>Description<textarea name="description" rows="5" maxlength="5000"><?= e($p['description']??'') ?></textarea></label><label>Product image URL<input name="image_url" maxlength="500" value="<?= e_attr($p['image_url']??'') ?>" placeholder="/images/product.webp or https://…"></label><div class="grid2"><label>Display order<input type="number" min="0" name="sort_order" value="<?= (int)($p['sort_order']??0) ?>"></label><label>Stock quantity<input type="number" min="0" name="stock_quantity" value="<?= e_attr((string)($p['stock_quantity']??'')) ?>"></label></div><div class="option-grid"><label class="choice-row"><input type="checkbox" name="active" <?= !isset($p['active'])||(int)$p['active']?'checked':'' ?>><span><strong>Available in store</strong><small>Customers can see and add this product.</small></span></label><label class="choice-row"><input type="checkbox" name="featured" <?= !empty($p['featured'])?'checked':'' ?>><span><strong>Featured</strong><small>Place this product before standard items.</small></span></label><label class="choice-row"><input type="checkbox" name="track_inventory" <?= !empty($p['track_inventory'])?'checked':'' ?>><span><strong>Track inventory</strong><small>Prevent orders beyond the available quantity.</small></span></label></div><div class="action-bar"><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/store/products">Cancel</a><button class="btn">Save product</button></div></form><aside class="card commerce-guidance"><p class="section-kicker">Store readiness</p><h2>Before publishing</h2><ul><li>Use a stable SKU for fulfillment.</li><li>Confirm the image is readable on the public site.</li><li>Enable inventory tracking for limited items.</li><li>Keep pricing clear and current.</li></ul></aside></div>
